        self.assertEqual(ledger_by_api["top_list"]["parquet_status"], "not_enabled")
        self.assertEqual(ledger_by_api["top_inst"]["call_status"], "empty")
        self.assertEqual(ledger_by_api["stk_limit"]["call_status"], "success")
