    def test_one_click_launcher_rejects_nonlocal_urls_without_leaking_secrets(self):
        launcher_path = Path("scripts/start_command_center_3.command")
        launcher = launcher_path.read_text(encoding="utf-8")

        self.assertIn("safe_display_url", launcher)
        self.assertIn("safe_display_open_url", launcher)
        self.assertIn('APP_OPEN_URL="$(safe_display_open_url "$APP_URL")', launcher)
        self.assertIn('APP_URL_DISPLAY="$APP_OPEN_URL"', launcher)
        self.assertIn("url_is_local", launcher)
        self.assertIn('if ! url_is_local "$API_BASE"; then', launcher)
        self.assertIn('open "$APP_OPEN_URL"', launcher)
        self.assertNotIn('open "$APP_URL"', launcher)
        self.assertIn("displayed and opened launcher URLs are sanitized", launcher)
        self.assertIn("query/userinfo are stripped", launcher)
        self.assertIn("普通恢复动作：打开今日作战台或桌面壳预检查看 P0 四段联通；P0 未 ready 时不要进入 P1 确认按钮。", launcher)
        self.assertIn("日志定位：FastAPI=${FASTAPI_LOG}；React/Vite=${VITE_LOG}。", launcher)
        self.assertIn("安全边界：失败诊断不会自动重试、不会创建 POST task、不会调用 Tushare/DeepSeek/GitHub，也不会读取 token/key。", launcher)
        self.assertLess(
            launcher.index('if ! url_is_local "$API_BASE"; then'),
            launcher.index('if [ "$LAUNCHER_CHECK_ONLY" = "1" ]; then'),
        )
        self.assertLess(
            launcher.index('if ! url_is_local "$API_BASE"; then'),
            launcher.index('mkdir -p "$LOG_DIR"'),
        )

        env = os.environ.copy()
        env.update(
            {
                "STOCK_MING_PYTHON": sys.executable,
                "COMMAND_CENTER_3_LAUNCHER_CHECK_ONLY": "1",
                "VITE_API_BASE_URL": "https://user:SHOULD_DROP@example.com:9443/api?token=SHOULD_DROP#secret",
            }
        )
        result = subprocess.run(
            ["bash", str(launcher_path)],
            cwd=Path.cwd(),
            env=env,
            text=True,
            capture_output=True,
            check=False,
        )
        combined = f"{result.stdout}\n{result.stderr}"

        self.assertNotEqual(result.returncode, 0)
        self.assertIn("FastAPI API base 必须是本机地址：https://example.com:9443/api", combined)
        self.assertIn("不会探测非本机 API base", combined)
        self.assertIn("不打印 query/hash/username/password", combined)
        self.assertNotIn("SHOULD_DROP", combined)
        self.assertNotIn("user:", combined)
        self.assertNotIn("?token=", combined)
        self.assertNotIn("#secret", combined)
        self.assertNotIn("Starting FastAPI", combined)
        self.assertNotIn("Starting React/Vite", combined)

        local_env = os.environ.copy()
        local_env.update(
            {
                "STOCK_MING_PYTHON": sys.executable,
                "COMMAND_CENTER_3_LAUNCHER_CHECK_ONLY": "1",
                "VITE_API_BASE_URL": "http://user:SHOULD_DROP@127.0.0.1:8710/api?token=SHOULD_DROP#secret",
                "COMMAND_CENTER_3_VITE_URL": "http://user:SHOULD_DROP@localhost:5173?token=SHOULD_DROP#secret",
                "COMMAND_CENTER_3_APP_URL": "http://user:SHOULD_DROP@localhost:5173/#home?token=SHOULD_DROP#secret",
            }
        )
        local_result = subprocess.run(
            ["bash", str(launcher_path)],
            cwd=Path.cwd(),
            env=local_env,
            text=True,
            capture_output=True,
            check=False,
        )
        local_output = f"{local_result.stdout}\n{local_result.stderr}"

        self.assertEqual(local_result.returncode, 0, local_output)
        self.assertIn("FastAPI: http://127.0.0.1:8710/api", local_output)
        self.assertIn("React/Vite: http://localhost:5173", local_output)
        self.assertIn("Open route: http://localhost:5173/", local_output)
        self.assertIn("open_route=http://localhost:5173/", local_output)
        self.assertIn("Check-only mode", local_output)
        self.assertNotIn("SHOULD_DROP", local_output)
        self.assertNotIn("user:", local_output)
        self.assertNotIn("?token=", local_output)
        self.assertNotIn("#secret", local_output)
        self.assertNotIn("Starting FastAPI", local_output)
        self.assertNotIn("Starting React/Vite", local_output)

        check_only_wrapper_path = Path("scripts/check_command_center_3.command")
        self.assertTrue(check_only_wrapper_path.exists())
        self.assertTrue(os.access(check_only_wrapper_path, os.X_OK))
        wrapper_result = subprocess.run(
            ["bash", str(check_only_wrapper_path)],
            cwd=Path.cwd(),
            env=local_env,
            text=True,
            capture_output=True,
            check=False,
        )
        wrapper_output = f"{wrapper_result.stdout}\n{wrapper_result.stderr}"

        self.assertEqual(wrapper_result.returncode, 0, wrapper_output)
        self.assertIn("Command Center 3.0 check-only launcher", wrapper_output)
        self.assertIn("Check-only mode", wrapper_output)
        self.assertIn("Browser open: skipped", wrapper_output)
        self.assertIn("does not start FastAPI/Vite", wrapper_output)
        self.assertNotIn("SHOULD_DROP", wrapper_output)
        self.assertNotIn("user:", wrapper_output)
        self.assertNotIn("?token=", wrapper_output)
        self.assertNotIn("#secret", wrapper_output)
        self.assertNotIn("Starting FastAPI", wrapper_output)
        self.assertNotIn("Starting React/Vite", wrapper_output)

