    def test_worker_runtime_cache_detects_redis_config_without_exposing_env_or_value(self):
        old_values = {name: os.environ.get(name) for name, _label in worker_service.REDIS_CONFIG_ENV_SOURCES}
        for name, _label in worker_service.REDIS_CONFIG_ENV_SOURCES:
            os.environ.pop(name, None)
        os.environ["COMMAND_CENTER_REDIS_URL"] = "redis://SHOULD_DROP@127.0.0.1:6379/0"
        self.addCleanup(
            lambda: [
                os.environ.pop(name, None) if value is None else os.environ.__setitem__(name, value)
                for name, value in old_values.items()
            ]
        )

        packet = worker_service.read_worker_runtime_cache()
        preflight = packet["worker_runtime_dependency_preflight"]
        packet_dump = json.dumps(packet, ensure_ascii=False)

        self.assertTrue(preflight["redis_url_configured"])
        self.assertEqual(preflight["redis_config_sources_present"], ["command_center_redis_url"])
        self.assertEqual(preflight["redis_config_source_count"], 1)
        self.assertFalse(preflight["redis_config_values_exposed"])
        self.assertFalse(preflight["redis_config_env_names_exposed"])
        self.assertNotIn("redis://SHOULD_DROP", packet_dump)
        self.assertNotIn("COMMAND_CENTER_REDIS_URL", packet_dump)
        self.assertFalse(preflight["redis_pinged"])
        self.assertFalse(preflight["worker_started"])
        self.assertFalse(preflight["celery_worker_started"])
        self.assertFalse(preflight["external_calls_triggered"])
        self.assertTrue(preflight["does_not_execute_trades"])

    def test_worker_synthetic_healthcheck_endpoint_runs_local_task_only(self):
        self._with_meta_store()
        clear_task_statuses_for_tests(clear_persisted=True)

        response = self.client.post(
            "/api/worker/synthetic-healthcheck",
            json={"requested_from": "test", "api_key": "SHOULD_DROP"},
        ).json()

        self.assertTrue(response["ok"])
        packet = response["data"]
        self.assertEqual(packet["packet_key"], "command_center_3_worker_synthetic_healthcheck_packet")
        self.assertEqual(packet["status"], "synthetic_healthcheck_passed_local_task_store_only")
        self.assertTrue(packet["synthetic_healthcheck_executed"])
        self.assertTrue(packet["healthcheck_task_dispatched"])
        self.assertTrue(packet["local_task_round_trip_verified"])
        self.assertTrue(packet["task_log_round_trip_verified"])
        self.assertEqual(packet["healthcheck_hash_algorithm"], "sha256")
        self.assertEqual(len(packet["task_identity_sha256"]), 64)
        self.assertEqual(len(packet["readback_task_identity_sha256"]), 64)
        self.assertTrue(packet["task_readback_hash_matches"])
        self.assertFalse(packet["celery_worker_started"])
        self.assertFalse(packet["redis_pinged"])
        self.assertFalse(packet["scheduler_started"])
        self.assertFalse(packet["production_worker_complete"])
        self.assertFalse(packet["activation_ready"])
        self.assertFalse(packet["external_calls_triggered"])
        self.assertFalse(packet["tushare_called"])
        self.assertFalse(packet["deepseek_called"])
        self.assertFalse(packet["github_called"])
        self.assertTrue(packet["does_not_execute_trades"])
        self.assertTrue(packet["does_not_modify_strategy_action"])
        self.assertEqual(response["call_ledger"][0]["api"], "local_worker_synthetic_healthcheck")
        self.assertFalse(response["call_ledger"][0]["external"])
        self.assertNotIn("SHOULD_DROP", json.dumps(response, ensure_ascii=False))

        cache = self.client.get("/api/worker/cache").json()["data"]
        self.assertEqual(cache["worker_synthetic_healthcheck"]["task_id"], packet["task_id"])
        self.assertTrue(cache["worker_synthetic_healthcheck"]["synthetic_healthcheck_executed"])
        self.assertTrue(cache["worker_synthetic_healthcheck"]["task_readback_hash_matches"])
        self.assertFalse(cache["worker_synthetic_healthcheck"]["production_worker_complete"])
        self.assertFalse(cache["worker_synthetic_healthcheck"]["external_calls_triggered"])

